refentry.refsect1:
&reftitle.description;
arrayarray_keys arrayarray
arrayarray_keys arrayarray mixedfilter_value boolstrict&false;
array_keys ले array from का numeric र string keys return गर्दछ।
यदि filter_value तोकिएको छ भने, उक्त value का लागि मात्र keys return गरिन्छ। अन्यथा, array from का सबै keys return गरिन्छ।

  &reftitle.examples;



    array_keys को उदाहरण


<?php
$array = array(0 => 100, "color" => "red");
print_r(array_keys($array));

$array = array("blue", "red", "green", "blue", "blue");
print_r(array_keys($array, "blue"));

$array = array("color" => array("blue", "red", "green"),
               "size"  => array("small", "medium", "large"));
print_r(array_keys($array));
?>


    &example.outputs;


Array
(
    [0] => 0
    [1] => color
)
Array
(
    [0] => 0
    [1] => 3
    [2] => 4
)
Array
(
    [0] => color
    [1] => size
)
